    /// <summary>A compiled fnmatch pattern: '*', '?', '[seq]', '[!seq]' (CPython's fnmatch._translate, matched directly).</summary>
    internal sealed class FnPattern
    {
        abstract class Token { public abstract bool Matches(char c); }
        sealed class Star : Token { public override bool Matches(char c) => true; }
        sealed class AnyChar : Token { public override bool Matches(char c) => true; }
        sealed class Literal : Token { public readonly char C; public Literal(char c) { C = c; } public override bool Matches(char c) => c == C; }
        sealed class CharSet : Token
        {
            public readonly bool Negate;
            public readonly List<(char Lo, char Hi)> Ranges = new List<(char, char)>();
            public CharSet(bool negate) { Negate = negate; }
            public override bool Matches(char c)
            {
                bool hit = false;
                foreach (var (lo, hi) in Ranges) if (c >= lo && c <= hi) { hit = true; break; }
                return hit != Negate;
            }
        }
        sealed class Never : Token { public override bool Matches(char c) => false; }

        readonly List<Token> _tokens = new List<Token>();
        static readonly Dictionary<string, FnPattern> Cache = new Dictionary<string, FnPattern>();

        public static FnPattern Of(string pat)
        {
            lock (Cache)
            {
                if (Cache.TryGetValue(pat, out var p)) return p;
                if (Cache.Count > 4096) Cache.Clear();
                return Cache[pat] = new FnPattern(pat);
            }
        }

        FnPattern(string pat)
        {
            int i = 0, n = pat.Length;
            while (i < n)
            {
                char c = pat[i++];
                if (c == '*')
                {
                    _tokens.Add(new Star());
                    while (i < n && pat[i] == '*') i++;
                }
                else if (c == '?') _tokens.Add(new AnyChar());
                else if (c == '[')
                {
                    int j = i;
                    if (j < n && pat[j] == '!') j++;
                    if (j < n && pat[j] == ']') j++;
                    while (j < n && pat[j] != ']') j++;
                    if (j >= n) { _tokens.Add(new Literal('[')); continue; }
                    _tokens.Add(Set(pat, i, j));
                    i = j + 1;
                }
                else _tokens.Add(new Literal(c));
            }
        }

        /// <summary>The set pat[i:j] (inside the brackets), with CPython's chunking of ranges and removal of empty ranges.</summary>
        static Token Set(string pat, int i, int j)
        {
            string stuff = pat.Substring(i, j - i);
            List<string> chunks;
            if (stuff.IndexOf('-') < 0) chunks = new List<string> { stuff };
            else
            {
                chunks = new List<string>();
                int k = pat[i] == '!' ? i + 2 : i + 1;
                while (true)
                {
                    k = k < j ? pat.IndexOf('-', k, j - k) : -1;
                    if (k < 0) break;
                    chunks.Add(pat.Substring(i, k - i));
                    i = k + 1;
                    k += 3;
                }
                string chunk = pat.Substring(i, j - i);
                if (chunk.Length > 0) chunks.Add(chunk);
                else chunks[chunks.Count - 1] += "-";
                for (int m = chunks.Count - 1; m > 0; m--)
                    if (chunks[m - 1][chunks[m - 1].Length - 1] > chunks[m][0])
                    {
                        chunks[m - 1] = chunks[m - 1].Substring(0, chunks[m - 1].Length - 1) + chunks[m].Substring(1);
                        chunks.RemoveAt(m);
                    }
            }
            if (chunks.Count == 1 && chunks[0].Length == 0) return new Never();
            if (chunks.Count == 1 && chunks[0] == "!") return new AnyChar();
            bool negate = chunks[0].Length > 0 && chunks[0][0] == '!';
            if (negate) chunks[0] = chunks[0].Substring(1);
            var set = new CharSet(negate);
            // consecutive chunks are joined by a range: the last char of one to the first char of the next
            for (int m = 0; m < chunks.Count; m++)
            {
                string s = chunks[m];
                int start = 0, end = s.Length;
                if (m > 0) { set.Ranges.Add((chunks[m - 1][chunks[m - 1].Length - 1], s[0])); start = 1; }
                if (m < chunks.Count - 1) end--;
                for (int t = start; t < end; t++) set.Ranges.Add((s[t], s[t]));
            }
            return set;
        }

        /// <summary>Does the whole name match (re.match with the pattern's \z)?</summary>
        public bool Match(string name)
        {
            int p = 0, s = 0, starP = -1, starS = -1;
            while (s < name.Length)
            {
                if (p < _tokens.Count && !(_tokens[p] is Star) && _tokens[p].Matches(name[s])) { p++; s++; }
                else if (p < _tokens.Count && _tokens[p] is Star) { starP = p++; starS = s; }
                else if (starP >= 0) { p = starP + 1; s = ++starS; }
                else return false;
            }
            while (p < _tokens.Count && _tokens[p] is Star) p++;
            return p == _tokens.Count;
        }

        static string NormCase(string s) => OperatingSystem.IsWindows() ? s.Replace('/', '\\').ToLowerInvariant() : s;
        public static bool FnMatch(string name, string pat) => Of(NormCase(pat)).Match(NormCase(name));
        public static bool FnMatchCase(string name, string pat) => Of(pat).Match(name);
    }

    /// <summary>CPython's glob algorithm (_iglob, _glob0, _glob1, _glob2, _rlistdir) over the file system.</summary>
    internal static class Globber
    {
        static char Sep => System.IO.Path.DirectorySeparatorChar;

        /// <summary>os.path.split</summary>
        internal static (string Head, string Tail) Split(string p)
        {
            int i = Math.Max(p.LastIndexOf('/'), OperatingSystem.IsWindows() ? p.LastIndexOf('\\') : -1) + 1;
            string head = p.Substring(0, i), tail = p.Substring(i);
            if (head.Length > 0 && head.Any(c => c != '/' && c != Sep)) head = head.TrimEnd('/', Sep);
            return (head, tail);
        }

        /// <summary>os.path.join of two parts.</summary>
        internal static string PathJoin(string a, string b)
        {
            if (b.StartsWith("/") || OperatingSystem.IsWindows() && System.IO.Path.IsPathRooted(b)) return b;
            if (a.Length == 0 || a.EndsWith("/") || a.EndsWith(Sep.ToString())) return a + b;
            return a + Sep + b;
        }

        /// <summary>glob's _join: the other part when one is empty.</summary>
        static string Join(string dirname, string basename) => dirname.Length == 0 || basename.Length == 0 ? dirname + basename : PathJoin(dirname, basename);

        internal static bool HasMagic(string s) => s.IndexOfAny(new[] { '*', '?', '[' }) >= 0;
        static bool IsHidden(string path) => path.Length > 0 && path[0] == '.';
        static bool IsRecursive(string pattern) => pattern == "**";

        internal static bool LExists(string p)
        {
            if (p.Length == 0) return false;
            try { return File.Exists(p) || Directory.Exists(p) || new FileInfo(p).LinkTarget != null; }
            catch (Exception) { return false; }
        }

        internal static bool IsDir(string p) => p.Length > 0 && Directory.Exists(p);

        static List<string> ListDir(string dirname, bool dironly)
        {
            var names = new List<string>();
            try
            {
                string arg = dirname.Length == 0 ? "." : dirname;
                foreach (var entry in Directory.EnumerateFileSystemEntries(arg))
                {
                    string name = System.IO.Path.GetFileName(entry);
                    if (!dironly || Directory.Exists(entry)) names.Add(name);
                }
            }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
            catch (ArgumentException) { }
            return names;
        }

        static IEnumerable<string> Glob0(string dirname, string basename, bool dironly, bool includeHidden)
        {
            if (basename.Length > 0) { if (LExists(Join(dirname, basename))) return new[] { basename }; }
            else if (IsDir(dirname)) return new[] { basename };
            return Array.Empty<string>();
        }

        static IEnumerable<string> Glob1(string dirname, string pattern, bool dironly, bool includeHidden)
        {
            IEnumerable<string> names = ListDir(dirname, dironly);
            if (!(includeHidden || IsHidden(pattern))) names = names.Where(x => !IsHidden(x));
            var pat = FnPattern.Of(pattern);
            return names.Where(n => pat.Match(n)).ToList();
        }

        static IEnumerable<string> Glob2(string dirname, string pattern, bool dironly, bool includeHidden)
        {
            if (dirname.Length == 0 || IsDir(dirname)) yield return "";
            foreach (var x in RListDir(dirname, dironly, includeHidden)) yield return x;
        }

        static IEnumerable<string> RListDir(string dirname, bool dironly, bool includeHidden)
        {
            foreach (var x in ListDir(dirname, dironly))
            {
                if (!includeHidden && IsHidden(x)) continue;
                yield return x;
                string path = dirname.Length > 0 ? Join(dirname, x) : x;
                foreach (var y in RListDir(path, dironly, includeHidden)) yield return Join(x, y);
            }
        }

        internal static IEnumerable<string> IGlob(string pathname, string rootDir, bool recursive, bool dironly, bool includeHidden)
        {
            var (dirname, basename) = Split(pathname);
            if (!HasMagic(pathname))
            {
                if (basename.Length > 0) { if (LExists(Join(rootDir, pathname))) yield return pathname; }
                else if (IsDir(Join(rootDir, dirname))) yield return pathname;
                yield break;
            }
            if (dirname.Length == 0)
            {
                var found = recursive && IsRecursive(basename) ? Glob2(rootDir, basename, dironly, includeHidden) : Glob1(rootDir, basename, dironly, includeHidden);
                foreach (var x in found) yield return x;
                yield break;
            }
            IEnumerable<string> dirs = dirname != pathname && HasMagic(dirname) ? IGlob(dirname, rootDir, recursive, true, includeHidden) : new[] { dirname };
            Func<string, string, bool, bool, IEnumerable<string>> globInDir =
                HasMagic(basename) ? (recursive && IsRecursive(basename) ? Glob2 : Glob1) : Glob0;
            foreach (var d in dirs)
                foreach (var name in globInDir(Join(rootDir, d), basename, dironly, includeHidden))
                    yield return PathJoin(d, name);
        }
    }
}

namespace Typhon.Stdlib
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using System.Text;
    using Typhon.Runtime;

    /// <summary>glob: file names matching a shell pattern, in directory order (CPython's glob).</summary>
    internal static class glob_
    {
        public static List<string> glob(string pathname, string? root_dir = null, long? dir_fd = null, bool recursive = false, bool include_hidden = false) =>
            iglob(pathname, root_dir, dir_fd, recursive, include_hidden).ToList();

        public static IEnumerable<string> iglob(string pathname, string? root_dir = null, long? dir_fd = null, bool recursive = false, bool include_hidden = false)
        {
            if (dir_fd != null) throw new NotSupportedException("Typhon: glob with dir_fd is not supported");
            var it = Globber.IGlob(pathname, root_dir ?? "", recursive, false, include_hidden);
            bool skipEmpty = pathname.Length == 0 || recursive && pathname.Substring(0, Math.Min(2, pathname.Length)) == "**";
            return skipEmpty ? SkipFirstEmpty(it) : it;
        }

        static IEnumerable<string> SkipFirstEmpty(IEnumerable<string> it)
        {
            bool first = true;
            foreach (var s in it)
            {
                if (first) { first = false; if (s.Length == 0) continue; }
                yield return s;
            }
        }

        /// <summary>escape: wrap each of * ? [ in brackets, so the name matches only itself.</summary>
        public static string escape(string pathname)
        {
            var sb = new StringBuilder();
            foreach (char c in pathname) { if (c == '*' || c == '?' || c == '[') sb.Append('[').Append(c).Append(']'); else sb.Append(c); }
            return sb.ToString();
        }

        public static bool has_magic(string s) => Globber.HasMagic(s);
    }

    /// <summary>fnmatch: shell-style matching of names (case-insensitive only where the OS is).</summary>
    internal static class fnmatch_
    {
        public static bool fnmatch(string name, string pat) => FnPattern.FnMatch(name, pat);
        public static bool fnmatchcase(string name, string pat) => FnPattern.FnMatchCase(name, pat);
        public static List<string> filter(IEnumerable<string> names, string pat) => names.Where(n => FnPattern.FnMatch(n, pat)).ToList();
        public static List<string> filterfalse(IEnumerable<string> names, string pat) => names.Where(n => !FnPattern.FnMatch(n, pat)).ToList();
    }
